import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./FloodMap.css";
import L from 'leaflet';
import kaladyRiver from "../assets/kalady-river.png";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const ITEMS_PER_PAGE = 10;

// 🎨 HELPER: Risk Color Logic
const getRiskStatus = (depth, isNormalState) => {
  if (isNormalState) {
    return {
      color: "#10b981", 
      bg: "rgba(16, 185, 129, 0.1)",
      label: "Safe / Normal Flow",
      icon: "fa-check-circle",
      shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)"
    };
  }

  if (depth <= 3) return { color: "#10b981", bg: "rgba(16, 185, 129, 0.1)", label: "Low Risk", icon: "fa-check-circle", shadow: "0 4px 14px 0 rgba(16, 185, 129, 0.39)" };
  if (depth < 8) return { color: "#f59e0b", bg: "rgba(245, 158, 11, 0.1)", label: "Moderate Risk", icon: "fa-exclamation-circle", shadow: "0 4px 14px 0 rgba(245, 158, 11, 0.39)" };
  return { color: "#ef4444", bg: "rgba(239, 68, 68, 0.1)", label: "Critical Risk", icon: "fa-exclamation-triangle", shadow: "0 4px 14px 0 rgba(239, 68, 68, 0.39)" };
};

const generateSmartName = (osmData) => {
  if (!osmData) return "Unknown Location";
  const addr = osmData.address || {};
  const street = addr.road || addr.street || addr.pedestrian || addr.path || addr.lane;
  const area = addr.neighbourhood || addr.suburb || addr.residential || addr.village;
  const town = addr.town || addr.city || addr.county;
  if (street && area) return `${street}, ${area}`;
  if (street && town) return `${street}, ${town}`;
  if (area && town) return `${area}, ${town}`;
  if (osmData.display_name) return osmData.display_name.split(", ").slice(0, 2).join(", ");
  return town || "Flood Point";
};

// 📍 COMPONENT: Map Popup
const LocationPopup = ({ lat, lon, depth, isNormalState }) => {
  const [address, setAddress] = useState("Loading details...");
  const [title, setTitle] = useState("Location Details");
  const status = getRiskStatus(depth, isNormalState);

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        if (res.data) {
          setTitle(generateSmartName(res.data));
          setAddress(res.data.display_name);
        }
      } catch (err) { setAddress("Address unavailable"); }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div style={{ fontFamily: 'Inter, sans-serif', minWidth: '220px', padding: '5px' }}>
      <div style={{ color: status.color, fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '1px', marginBottom: '4px' }}>{status.label}</div>
      <strong style={{ fontSize: '15px', color: '#0f172a', display: 'block', marginBottom: '8px' }}>{title}</strong>
      {!isNormalState && (
        <div style={{ background: '#f8fafc', padding: '8px', borderRadius: '6px', marginBottom: '8px' }}>
          <span style={{ color: '#64748b', fontSize: '11px' }}>Water Depth:</span>
          <strong style={{ color: status.color, marginLeft: '5px', fontSize: '14px' }}>{depth}m</strong>
        </div>
      )}
      <div style={{ fontSize: '11px', color: '#94a3b8', lineHeight: '1.4' }}>
        <i className="fas fa-map-marker-alt" style={{ marginRight: '5px' }}></i>
        {address}
      </div>
    </div>
  );
};

const MapController = ({ targetLoc }) => {
  const map = useMap();
  useEffect(() => {
    if (targetLoc) { map.flyTo(targetLoc, 14, { animate: true, duration: 1.5 }); }
  }, [targetLoc, map]);
  return null;
};


const CustomMapControls = ({ onSearch, onFindMe }) => {
  const [query, setQuery] = useState("");
  const [searching, setSearching] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;
    setSearching(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`);
      if (res.data && res.data.length > 0) {
        const { lat, lon } = res.data[0];
        onSearch([parseFloat(lat), parseFloat(lon)]);
      }
    } catch (err) { console.error(err); }
    finally { setSearching(false); }
  };

  return (
<div className="map-controls-wrapper">      
      <form onSubmit={handleSearch} className="map-search-form">
        <input
          type="text" value={query} onChange={(e) => setQuery(e.target.value)}
          placeholder="Search location..."
          className="map-search-input"
        />
        <button type="submit" className="map-search-btn">
          {searching ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-search"></i>}
        </button>
      </form>
      <button onClick={onFindMe} className="map-locate-btn">
        <i className="fas fa-location-arrow"></i>
      </button>
    </div>
  );
};

const MapLegend = () => (
  <div className="map-legend">
    <h5 style={{ margin: '0 0 10px 0', fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '1px', opacity: 0.7 }}>Risk Scale</h5>
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '0.8rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}><span style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#ef4444', boxShadow: '0 0 10px #ef4444' }}></span> Critical</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}><span style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#f59e0b', boxShadow: '0 0 10px #f59e0b' }}></span> Moderate</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}><span style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#10b981', boxShadow: '0 0 10px #10b981' }}></span> Low Risk</div>
    </div>
  </div>
);

const Pagination = ({ currentPage, totalItems, onPageChange }) => {
  const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
  if (totalPages <= 1) return null;
  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px', marginTop: '20px' }}>
      <button onClick={() => onPageChange(currentPage - 1)} disabled={currentPage === 1} className="rd-nav-links" style={{ padding: '8px 15px', background: '#f1f5f9', border: 'none', borderRadius: '8px', cursor: 'pointer', color: '#475569' }}>Prev</button>
      <span style={{ fontSize: '0.9rem', fontWeight: '600' }}>{currentPage} / {totalPages}</span>
      <button onClick={() => onPageChange(currentPage + 1)} disabled={currentPage === totalPages} className="rd-nav-links" style={{ padding: '8px 15px', background: '#f1f5f9', border: 'none', borderRadius: '8px', cursor: 'pointer', color: '#475569' }}>Next</button>
    </div>
  );
};

const AffectedAreaItem = ({ data, index }) => {
  const [expanded, setExpanded] = useState(false);
  const [details, setDetails] = useState(null);
  const [loading, setLoading] = useState(false);
  const [displayName, setDisplayName] = useState(data.place);
  const status = getRiskStatus(data.depth, false);

  const fetchDetails = async () => {
    if (details || loading) return;
    setLoading(true);
    try {
      const res = await axios.get(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`);
      if (res.data) { setDetails(res.data); setDisplayName(generateSmartName(res.data)); }
    } catch (e) { setDetails({ error: true }); }
    finally { setLoading(false); }
  };

  useEffect(() => {
    if (data.depth >= 8) {
      const timer = setTimeout(() => fetchDetails(), index * 500);
      return () => clearTimeout(timer);
    }
  }, [data.depth, index]);

  return (
    <div className="rd-glass-card" style={{ marginBottom: '12px', borderLeft: `4px solid ${status.color}`, padding: '1.25rem', transition: '0.3s' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' }}>
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <div style={{ background: status.bg, color: status.color, width: '45px', height: '45px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem' }}>
            <i className={`fas ${status.icon}`}></i>
          </div>
          <div>
            <h4 style={{ margin: 0, fontSize: '1rem', color: '#1e293b', fontWeight: '700' }}>{displayName}</h4>
            <div style={{ display: 'flex', gap: '10px', alignItems: 'center', marginTop: '4px' }}>
              <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Depth: <strong>{data.depth}m</strong></span>
              <span style={{ padding: '2px 8px', background: status.bg, color: status.color, borderRadius: '4px', fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase' }}>{status.label}</span>
            </div>
          </div>
        </div>
        <button onClick={() => { if (!expanded) fetchDetails(); setExpanded(!expanded); }} style={{ background: 'transparent', border: '1px solid #e2e8f0', padding: '8px 12px', borderRadius: '8px', cursor: 'pointer', fontSize: '0.8rem', fontWeight: 600 }}>
          {expanded ? 'Hide' : 'Analyze'}
        </button>
      </div>
      {expanded && (
        <div style={{ marginTop: '15px', padding: '15px', background: '#f8fafc', borderRadius: '10px', fontSize: '0.85rem', color: '#475569', border: '1px solid #f1f5f9' }}>
          {loading ? 'Fetching geospatial data...' : details?.display_name || 'Details unavailable'}
        </div>
      )}
    </div>
  );
};

const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);
  const [severePage, setSeverePage] = useState(1);
  const [otherPage, setOtherPage] = useState(1);
  const [showAllAreas, setShowAllAreas] = useState(false);
  const [mapCenter, setMapCenter] = useState([10.16, 76.43]);
  const [searchPos, setSearchPos] = useState(null);
  const [userPos, setUserPos] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, { params: { level: simulatedLevel } });
        if (response.data) {
          if (response.data.data) response.data.data.sort((a, b) => b.depth - a.depth);
          setFloodData(response.data);
        }
      } catch (error) { console.error(error); }
      finally { setLoading(false); }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  const handleLocateUser = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((p) => {
        const c = [p.coords.latitude, p.coords.longitude];
        setUserPos(c); setMapCenter(c);
      });
    }
  };

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Syncing Satellite Data...</p></div>;

  const threshold = floodData?.current_water_level || 3.5;
  const isNormalState = threshold <= 3.0;
  const severeZones = floodData?.data?.filter(d => d.depth >= threshold) || [];
  const otherZones = floodData?.data?.filter(d => d.depth < threshold) || [];
  const currentSevere = severeZones.slice((severePage - 1) * ITEMS_PER_PAGE, severePage * ITEMS_PER_PAGE);
  const currentOther = otherZones.slice((otherPage - 1) * ITEMS_PER_PAGE, otherPage * ITEMS_PER_PAGE);
  
  const getAlert = (level) => {
    if (level < 3) {
        return {
        title: "Conditions Normal",
        message: "Water levels are within safe limits. No flood risk.",
        color: "#10b981",
        bg: "rgba(255, 255, 255, 0.95)",
        icon: "fa-check-circle"
        };
    }
    if (level < 8) {
        return {
        title: "Caution: Rising Water Level",
        message: "Water level is increasing. Low-lying areas may be affected.",
        color: "#f59e0b",
        bg: "rgba(255, 255, 255, 0.95)",
        icon: "fa-exclamation-circle"
        };
    }
    return {
        title: "⚠️ Flood Warning",
        message: "High flood risk detected. Immediate precautions required.",
        color: "#ef4444",
        bg: "rgba(255, 255, 255, 0.95)",
        icon: "fa-exclamation-triangle"
    };
  };

  const alertData = getAlert(threshold);

  return (
    <div className="rd-advanced-page" style={{ background: '#f1f5f9' }}>
      {/* INJECTED RESPONSIVE CSS */}
      <style>{`
        .header-floating-nav {
            position: absolute; top: 20px; left: 0; width: 100%; z-index: 1100;
            padding: 0 20px; box-sizing: border-box;
        }
        .hero-main-title { font-size: clamp(1.8rem, 5vw, 3.5rem); line-height: 1.2; margin: 15px 0; }
        .hero-sub-text { font-size: clamp(0.9rem, 2vw, 1.1rem); max-width: 600px; margin: 0 auto 20px auto; }
        .rd-status-card-top { 
            display: flex; align-items: center; gap: 20px; padding: 15px 25px; border-radius: 15px; 
            margin: 0 auto; width: fit-content; max-width: 90%;
        }
        .rd-content-container { padding: 0 15px; max-width: 1200px; margin: 0 auto; }
        .map-section-wrapper { 
            width: 100vw; margin-left: calc(-50vw + 50%); position: relative; height: 65vh; min-height: 400px; 
        }
        .map-controls-wrapper {
            position: absolute; top: 15px; left: 15px; z-index: 1000; display: flex; gap: 8px; flex-wrap: wrap;
        }
        .map-search-form {
            display: flex; background: rgba(255, 255, 255, 0.95); backdrop-filter: blur(8px);
            box-shadow: 0 4px 15px rgba(0,0,0,0.1); borderRadius: 12px; padding: 4px;
        }
        .map-search-input { padding: 8px 12px; border: none; outline: none; background: transparent; width: 160px; font-weight: 500; }
        .map-search-btn { background: #3b82f6; color: white; border: none; width: 36px; height: 36px; border-radius: 8px; cursor: pointer; }
        .map-locate-btn { 
            background: white; color: #3b82f6; border: none; width: 44px; height: 44px; border-radius: 10px; 
            box-shadow: 0 4px 15px rgba(0,0,0,0.1); cursor: pointer; 
        }
        .map-legend {
            position: absolute; bottom: 20px; right: 15px; z-index: 1000;
            background: rgba(15, 23, 42, 0.9); padding: 12px; borderRadius: 10px; color: white; width: 140px;
        }
        .floating-alert-box {
            position: absolute; top: 75px; left: 50%; transform: translateX(-50%); z-index: 1050;
            width: 90%; max-width: 600px; padding: 12px 16px; borderRadius: 10px; display: flex; align-items: center; 
            gap: 12px; backdrop-filter: blur(8px); box-shadow: 0 8px 25px rgba(0,0,0,0.15);
        }
        .rd-split-layout { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; margin-top: 30px; }
        
        @media (max-width: 850px) {
            .rd-split-layout { grid-template-columns: 1fr; }
            .floating-alert-box { top: 120px; }
            .map-section-wrapper { height: 50vh; }
            .hero-content-wrapper { padding: 40px 10px; }
            .rd-status-card-top { flex-direction: column; text-align: center; gap: 10px; }
            .status-val { font-size: 1.5rem !important; }
        }
      `}</style>

      {/* 1. HERO SECTION */}
      <div className="rd-hero-fullscreen" style={{ 
        position: 'relative', backgroundImage: `url(${kaladyRiver})`, backgroundSize: 'cover', backgroundPosition: 'center',
        minHeight: '40vh', display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden'
      }}>
        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, background: 'linear-gradient(180deg, rgba(15, 23, 42, 0.6) 0%, rgba(15, 23, 42, 0.8) 100%)', zIndex: 1 }}></div>

        {/* NAVIGATION OVERLAY (Fixed Overlap) */}
        <div className="header-floating-nav">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', maxWidth: '1200px', margin: '0 auto' }}>
            <div className="rd-logo" style={{ cursor: 'pointer', color: 'white', fontSize: '1.2rem', fontWeight: 'bold' }} onClick={() => navigate('/')}>
              <i className="fas fa-satellite-dish" style={{ marginRight: '8px' }}></i>
              Periyar<span style={{ fontWeight: 300 }}>Risk</span>
            </div>
            <button className="rd-nav-links" onClick={() => navigate('/river-forecast')} style={{ background: 'rgba(255,255,255,0.2)', border: '1px solid white', color: 'white', padding: '8px 15px', borderRadius: '8px', cursor: 'pointer', backdropFilter: 'blur(5px)' }}>
              <i className="fas fa-th-large" style={{ marginRight: '8px' }}></i> Dashboard
            </button>
          </div>
        </div>

        <div className="hero-content-wrapper" style={{ position: 'relative', zIndex: 2, textAlign: 'center', color: 'white' }}>
          <span className="hero-pill" style={{ background: 'rgba(59, 130, 246, 0.2)', backdropFilter: 'blur(4px)', border: '1px solid #3b82f6', padding: '5px 15px', borderRadius: '20px', fontSize: '0.8rem' }}>
            Geospatial Intelligence
          </span>
          <h1 className="hero-main-title">Flood Risk Analysis</h1>
          <p className="hero-sub-text">Live hydrological simulation for Periyar Basin based on current river level.</p>
          
          <div className="rd-status-card-top" style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255, 255, 255, 0.2)', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)' }}>
            <i className="fas fa-water" style={{ color: '#60a5fa', fontSize: '1.5rem' }}></i>
            <div style={{ textAlign: 'left' }}>
              <span style={{ fontSize: '0.7rem', opacity: 0.8, textTransform: 'uppercase' }}>Current Water Level</span>
              <p className="status-val" style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold' }}>{threshold}m</p>
            </div>
            <i className={`fas ${alertData.icon}`} style={{ fontSize: '1.5rem', color: alertData.color }}></i>
          </div>
        </div>
      </div>
      
      <main className="rd-content-container">
        {/* 2. MAP SECTION */}
        <section className="map-section-wrapper">
          <div className="floating-alert-box" style={{ background: alertData.bg, border: `1px solid ${alertData.color}`, color: alertData.color }}>
            <i className={`fas ${alertData.icon}`} style={{ fontSize: '1.2rem' }}></i>
            <div>
              <h4 style={{ margin: 0, fontWeight: '700', fontSize: '0.9rem' }}>{alertData.title}</h4>
              <p style={{ margin: 0, fontSize: '0.8rem' }}>{alertData.message}</p>
            </div>
          </div>

          <CustomMapControls onSearch={(pos) => { setMapCenter(pos); setSearchPos(pos); }} onFindMe={handleLocateUser} />
          <MapLegend />

          <MapContainer center={[10.16, 76.43]} zoom={13} style={{ height: "100%", width: "100%" }}>
            <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
            <MapController targetLoc={mapCenter} />
            {userPos && <CircleMarker center={userPos} radius={8} pathOptions={{ color: '#3b82f6', fillColor: '#3b82f6', fillOpacity: 0.8 }}><Popup>Your Location</Popup></CircleMarker>}
            {floodData?.data?.map((point, idx) => {
              const status = getRiskStatus(point.depth, isNormalState);
              return (
                <CircleMarker key={idx} center={[point.lat, point.lon]} radius={6} pathOptions={{ color: 'white', weight: 1, fillColor: status.color, fillOpacity: 0.8 }}>
                  <Tooltip direction="top" offset={[0, -5]}><div style={{ fontWeight: '700', color: status.color }}>{point.depth}m</div></Tooltip>
                  <Popup><LocationPopup {...point} isNormalState={isNormalState} /></Popup>
                </CircleMarker>
              );
            })}
          </MapContainer>
        </section>

        {/* 3. INFORMATION LISTS */}
        <div className="rd-split-layout">
          <div className="rd-dashboard-section">
            <div className="section-header">
              <h3><i className="fas fa-layer-group" style={{ color: '#3b82f6', marginRight: '10px' }}></i> Affected Areas</h3>
              <p className="section-subtitle" style={{ fontSize: '0.85rem', color: '#64748b' }}>Categorized impact based on current topography models.</p>
            </div>

            {isNormalState ? (
              <div style={{ textAlign: 'center', padding: '40px 0' }}>
                <div style={{ fontSize: '3rem', color: '#10b981', marginBottom: '10px' }}><i className="fas fa-shield-virus"></i></div>
                <h4 style={{ color: '#0f172a' }}>Hydrological Safety Confirmed</h4>
                <p style={{ color: '#64748b', fontSize: '0.9rem' }}>River levels are within the safe threshold. No active residential flooding.</p>
              </div>
            ) : (
              <div style={{ marginTop: '1.5rem' }}>
                {currentSevere.map((item, index) => (
                  <AffectedAreaItem key={index} data={item} index={index} />
                ))}
                <Pagination currentPage={severePage} totalItems={severeZones.length} onPageChange={setSeverePage} />
              </div>
            )}
          </div>

          <div className="rd-dashboard-section">
            <div className="section-header">
              <h3><i className="fas fa-info-circle" style={{ color: '#3b82f6', marginRight: '10px' }}></i> Analysis Status</h3>
            </div>
            
            <div className="rd-lime-list">
              <div className="rd-lime-item" style={{ borderLeft: `4px solid ${isNormalState ? '#10b981' : '#ef4444'}`, padding: '10px', background: 'white', marginBottom: '10px', borderRadius: '8px' }}>
                <span style={{ fontSize: '0.7rem', fontWeight: 'bold', color: '#64748b' }}>Condition</span>
                <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem' }}>{isNormalState ? "Environment is currently stable. No warnings issued." : "Elevated risk detected. Monitor local advisories."}</p>
              </div>
              <div className="rd-lime-item" style={{ borderLeft: '4px solid #3b82f6', padding: '10px', background: 'white', borderRadius: '8px' }}>
                <span style={{ fontSize: '0.7rem', fontWeight: 'bold', color: '#64748b' }}>Model</span>
                <p style={{ margin: '5px 0 0 0', fontSize: '0.85rem' }}>Using Satellite Lidar Topography combined with real-time river sensors.</p>
              </div>
            </div>

            {!isNormalState && otherZones.length > 0 && (
              <button onClick={() => setShowAllAreas(!showAllAreas)} style={{ marginTop: '20px', width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #3b82f6', background: 'transparent', color: '#3b82f6', fontWeight: 700, cursor: 'pointer' }}>
                {showAllAreas ? 'Hide Moderate Risk' : `Show ${otherZones.length} Moderate Risks`}
              </button>
            )}
          </div>
        </div>

        {showAllAreas && !isNormalState && (
          <div className="rd-dashboard-section" style={{ marginTop: '2rem' }}>
            <h3 style={{ fontSize: '1rem', marginBottom: '1.5rem' }}>Moderate Risk Zone Log</h3>
            {currentOther.map((item, index) => <AffectedAreaItem key={index} data={item} />)}
            <Pagination currentPage={otherPage} totalItems={otherZones.length} onPageChange={setOtherPage} />
          </div>
        )}
      </main>

      {/* 4. INSTITUTIONAL FOOTER */}
      <footer style={{ background: '#0f172a', color: 'white', padding: '40px 0', marginTop: '60px' }}>
        <div className="rd-content-container">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '30px' }}>
            <div>
             <h4>Periyar Flood Watch</h4>
             <p style={{ fontSize: '0.85rem', opacity: 0.7 }}>Developed by the Center for AI-IoT Innovations, Adi Shankara Institute of Engineering & Technology.</p>
            </div>
            <div>
              <h4>Quick Links</h4>
              <ul style={{ listStyle: 'none', padding: 0, fontSize: '0.85rem', opacity: 0.7 }}>
                <li><a href="#home" style={{ color: 'white', textDecoration: 'none' }}>Home</a></li>
                <li><a href="#about" style={{ color: 'white', textDecoration: 'none' }}>About System</a></li>
              </ul>
            </div>
            <div>
              <h4>Institution</h4>
              <p style={{ fontSize: '0.85rem', opacity: 0.7 }}>Adi Shankara Institute of Engineering & Technology, Kalady</p>
            </div>
          </div>
          <div style={{ textAlign: 'center', marginTop: '40px', paddingTop: '20px', borderTop: '1px solid rgba(255,255,255,0.1)', fontSize: '0.8rem', opacity: 0.5 }}>
            <p>© {new Date().getFullYear()} Center for AI-IoT Innovations. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default FloodMap;
